#include "ksGlobalMatrixTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Global matrix semantic property failed");}
int main(){using T=ks::GlobalMatrixTask;uint64_t cases=0;auto verify=[&](unsigned amount,unsigned depth,unsigned bias,unsigned seed,unsigned factor,unsigned recurrenceBias,unsigned base){T t;std::array<uint16_t,12> memory{};std::array<uint16_t,6> expected{};auto next=uint16_t(seed);for(unsigned i=0;i<6;++i){expected[i]=next;next=uint16_t((uint32_t(uint16_t(next<<1))*factor>>16)+recurrenceBias);}auto mult=amount*depth;auto combined=uint16_t((uint16_t(uint8_t((mult>>8)+bias))<<8)|uint8_t(mult));auto target=uint16_t(combined<<1);unsigned root=0;while((root+1)*(root+1)<=target)++root;unsigned children=0,generated=0,tail=0,uploads=0,guard=0;auto read=[&](T::Read r)->uint32_t{switch(r){case T::Read::Amount:return amount;case T::Read::Depth:return depth;case T::Read::Bias:return bias;case T::Read::Seed:return seed;case T::Read::Factor:return factor;case T::Read::RecurrenceBias:return recurrenceBias;case T::Read::Base:return base;case T::Read::Tail:return uint16_t(seed+t.index()*977);case T::Read::Coefficient:return memory[t.index()];}return 0;};auto write=[&](T::Write w,uint16_t value){if(w==T::Write::Generated){check(t.index()==generated&&value==expected[generated]);memory[generated++]=value;}else{check(t.index()==tail&&value==uint16_t(seed+tail*977));memory[6+tail++]=value;}};
 while(t.stage()!=T::Stage::Complete){check(++guard<600);auto c=t.child();if(c!=T::Child::None){if(c==T::Child::First)check(t.combined()==combined);if(c==T::Child::Root)check(t.target()==target);if(c==T::Child::Gain)check(t.gainProduct()==0x599au*uint16_t(root*128+0x7fff));if(c==T::Child::Coefficient){check(t.index()==uploads&&t.offset()==0x825+uploads);auto expectedWord=uint32_t(uint16_t((uint32_t(uint16_t(memory[uploads]<<1))*base)>>16))*256;check(t.quantized()==expectedWord);++uploads;}check(t.resumeChild(uint8_t(root)));++children;continue;}auto cost=t.nextClocks(),s=unsigned(t.stage());check(t.advanceBefore(cost-1,read,write)==0&&unsigned(t.stage())==s);check(t.advanceBefore(cost,read,write)==cost);}
 check(children==17&&generated==6&&tail==6&&uploads==12);++cases;};
 for(unsigned amount=0;amount<256;++amount)for(unsigned depth=0;depth<256;++depth)verify(amount,depth,128,0x1234,0x8899,0x1040,44100);
 for(unsigned seed=0;seed<65536;++seed)verify(seed&255,seed>>8,(seed*17)&255,seed,(seed*149)&65535,seed^0xa55a,seed^0x55aa);
 std::cout<<"PASS: "<<cases<<" pure matrix properties; all amount/depth pairs, full16-bit seed/factor/bias/base permutations, independent6-step recurrence,6tail words,12 ordered fixed-width quantizations, native sqrt target/gain,17child lifetime, budget refusal\n";}
